def language_key(language: str | None) -> str:
    raw = (language or "en").strip().lower()
    aliases = {"english": "en", "hindi": "hi", "telugu": "te", "tamil": "ta",
        "kannada": "kn", "malayalam": "ml", "bengali": "bn", "marathi": "mr",
        "gujarati": "gu", "punjabi": "pa"}
    value = aliases.get(raw, raw.replace("_", "-").split("-", 1)[0])
    return value if value in CONSENT_TEXT else "en"


def is_supported_language(language: str | None) -> bool:
    raw = (language or "en").strip().lower()
    aliases = {"english", "hindi", "telugu", "tamil", "kannada", "malayalam", "bengali", "marathi", "gujarati", "punjabi"}
    code = raw.replace("_", "-").split("-", 1)[0]
    return raw in aliases or code in CONSENT_TEXT


def consent_version(retention_days: int) -> str:
    return f"{CONSENT_VERSION}-r{retention_days}"
